import{_ as o,o as i,c as a,a2 as d}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"에셋이 들어오는 길","description":"","frontmatter":{},"headers":[],"relativePath":"design/Asset-Pipeline.md","filePath":"design/Asset-Pipeline.md"}'),s={name:"design/Asset-Pipeline.md"};function c(t,e,n,l,r,h){return i(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="에셋이-들어오는-길" tabindex="-1">에셋이 들어오는 길 <a class="header-anchor" href="#에셋이-들어오는-길" aria-label="Permalink to &quot;에셋이 들어오는 길&quot;">​</a></h1><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/isometric-grammar.svg?raw=true" alt="에셋에서 칸에 누가 서 있고 어느 쪽을 보며 어디까지 보이는지 확인하는 기준"></p><h2 id="처음부터-승인까지" tabindex="-1">처음부터 승인까지 <a class="header-anchor" href="#처음부터-승인까지" aria-label="Permalink to &quot;처음부터 승인까지&quot;">​</a></h2><p>사용 권리를 확인한 입력에서 시작해 2D 생성, TRELLIS 출력, 원본 보존, Blender 정리, Unity 가져오기, 사람의 검수를 거쳐 승인된 에셋이 됩니다. 이 순서는 기본 경로입니다. 초상, UI 콘셉트, 타이틀 아트, UI 키트, 프롭, 타일, 4방향 클립, 시네마틱은 같은 그래프에서 의도에 따라 노드가 켜지거나 건너뛰어집니다.</p><h2 id="의도에서-그래프가-만들어지는-방식" tabindex="-1">의도에서 그래프가 만들어지는 방식 <a class="header-anchor" href="#의도에서-그래프가-만들어지는-방식" aria-label="Permalink to &quot;의도에서 그래프가 만들어지는 방식&quot;">​</a></h2><p>에셋 한 건은 별도 파이프라인 스크립트로 시작하지 않습니다. 의도를 넣고 그래프를 컴파일한 뒤, 분기 검사를 통과해야만 다음 단계로 갑니다.</p><p>의도 필드:</p><ul><li><code>asset_class</code>: <code>portrait</code> · <code>character_mesh</code> · <code>prop</code> · <code>tile</code> · <code>animation_clip</code> · <code>identity_lock</code> · <code>ui_concept</code> · <code>title_art</code> · <code>ui_kit</code></li><li><code>animation_need</code>: <code>none</code> · <code>four_dir_clip</code> · <code>cinematic_keyframe</code> · <code>previs</code></li><li><code>dcc</code>: <code>auto</code> · <code>blender</code> · <code>maya</code></li><li><code>generation_backend</code>: <code>nanobanana_gemini</code> · <code>grok_imagine</code> · <code>openai_image</code> · <code>trellis_v1</code> · <code>comfyui_trellis</code> · <code>none</code></li><li><code>rights_status</code>: <code>allowed</code> · <code>blocked</code> · <code>unresolved</code></li><li><code>source</code>: <code>generate</code> · <code>existing</code></li></ul><p><code>dcc: auto</code>는 Blender입니다. 4방향 전술 클립도 Blender입니다. Maya는 시네마틱 키프레임 연마가 필요할 때만 고릅니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/art/pipeline-graph.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --intent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/art/intents/character-four-dir.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/art/pipeline-graph.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --graph</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> graph.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blender=1,trellis=1,maya=0,animo=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/art/pipeline-graph.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate-manifest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --manifest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manifest.json</span></span></code></pre></div><p>컴파일은 구조만 만듭니다. 분기 검사가 호스트와 권리, 사람 검수 노드 존재를 닫힌 실패로 판정합니다. <code>blocked</code> 또는 <code>unresolved</code> 권리는 권리 확인 노드만 남기고 생성을 진행하지 않습니다.</p><h2 id="기본-캐릭터-메시-경로" tabindex="-1">기본 캐릭터 메시 경로 <a class="header-anchor" href="#기본-캐릭터-메시-경로" aria-label="Permalink to &quot;기본 캐릭터 메시 경로&quot;">​</a></h2><p><code>character_mesh</code> + <code>four_dir_clip</code> + <code>dcc: auto</code>는 다음 순서입니다.</p><p>권리 확인 → 2D 생성 → TRELLIS → 원본 보존 → Blender 정리 → 리깅 → Blender 4방향 애니 → FBX 보내기 → Unity 가져오기 → 사람 검수 → BOM 승인</p><p>이 경로에는 Maya나 Animo 노드가 없습니다. Animo는 <code>animo_not_on_auto_path</code>로 건너뛴 기록만 남깁니다.</p><p>초상, UI 콘셉트, 타이틀 아트, UI 키트, 타일은 2D 생성과 보존, 사람 검수까지만 갑니다. 프롭은 TRELLIS와 Blender 정리까지 가되 애니 노드는 켜지 않습니다.</p><h2 id="_2d-백엔드와-trellis" tabindex="-1">2D 백엔드와 TRELLIS <a class="header-anchor" href="#_2d-백엔드와-trellis" aria-label="Permalink to &quot;2D 백엔드와 TRELLIS&quot;">​</a></h2><p>2D 생성 백엔드는 <code>nanobanana_gemini</code>, <code>grok_imagine</code>, <code>openai_image</code> 세 종류다. 노드 메타데이터로 각각 구분해 남깁니다. POC 3D는 <code>trellis_v1</code>이며 노드는 <code>tool: trellis</code>, <code>model: microsoft/TRELLIS-image-large</code>입니다. 직접 Python 경로를 ComfyUI로 표기하지 않으며, <code>comfyui_trellis</code>는 기존 의도가 커뮤니티 실행을 요구할 때만 남깁니다.</p><p>ComfyUI를 쓸 때는 모델, 노드, Python, Torch, CUDA와 외부 휠 버전을 고정합니다. 기본 제공 노드를 우선 사용하며 외부 노드는 필요한 기능이 확인된 경우에만 저장소, 커밋, 라이선스와 배포 파일 해시를 검토합니다.</p><h2 id="blender에서-손보는-것" tabindex="-1">Blender에서 손보는 것 <a class="header-anchor" href="#blender에서-손보는-것" aria-label="Permalink to &quot;Blender에서 손보는 것&quot;">​</a></h2><ul><li>축과 1.5m 타일 기준 스케일 정리</li><li>중복 정점과 잘못된 노멀 수정</li><li>게임용 토폴로지와 UV 작성</li><li>색상, 법선, 거칠기 등 재질 채널 검토</li><li>캐릭터 리깅 또는 소품 피벗 설정</li><li>LOD와 단순 충돌체 생성</li><li>4방향 전술 클립과 기본 키프레임</li></ul><h2 id="maya와-animo-분기" tabindex="-1">Maya와 Animo 분기 <a class="header-anchor" href="#maya와-animo-분기" aria-label="Permalink to &quot;Maya와 Animo 분기&quot;">​</a></h2><p>Animo v10은 Autodesk Maya 2022–2026용 애니메이터 툴셋입니다. Tools Editor와 단축키로 도구를 모으고, 레퍼런스·영상 가져오기, 스페이스 전환, 베이크, 플레이블라스트를 돕습니다. 메시를 만들거나 TRELLIS를 대체하지 않습니다.</p><p>Animo 노드는 아래를 모두 만족할 때만 그래프에 들어갑니다.</p><ul><li><code>animation_need</code>가 <code>cinematic_keyframe</code></li><li><code>dcc</code>가 <code>maya</code></li><li>에셋이 캐릭터 메시 또는 애니 클립</li><li>앞 노드에 권리 확인과 Blender 정리·리깅이 있음</li></ul><p>이때 순서는 정해져 있습니다. Blender 리깅 다음, Unity 가져오기 전입니다. Animo만 따로 실행하는 경로는 금지이며 분기 검사는 <code>animo_standalone_forbidden</code>으로 거절합니다. Maya나 Animo가 호스트에 없으면 <code>maya_missing</code> / <code>animo_missing</code>으로 닫힌 실패고, 초상·타일·4방향 클립에 Maya를 지정하면 컴파일이 거절됩니다.</p><p>Animo는 저장소에 넣지 않습니다. 상용 사용은 업스트림 조건(무료, 재판매 금지, 베타)을 따르고, 설치된 경로만 <code>ANIMO_ROOT</code>로 검사합니다.</p><h2 id="unity에서-확인하는-것" tabindex="-1">Unity에서 확인하는 것 <a class="header-anchor" href="#unity에서-확인하는-것" aria-label="Permalink to &quot;Unity에서 확인하는 것&quot;">​</a></h2><ul><li>가져오기 도구의 정확한 버전과 설정 기록</li><li>재질과 텍스처 연결 검증</li><li>실제 크기, 피벗, 충돌체와 LOD 확인</li><li>고정 아이소메트릭 카메라에서 가독성 캡처</li></ul><h2 id="기증-에셋-오드랜드-패이로드-2026-09-07" tabindex="-1">기증 에셋: 오드랜드 패이로드 (2026-09-07) <a class="header-anchor" href="#기증-에셋-오드랜드-패이로드-2026-09-07" aria-label="Permalink to &quot;기증 에셋: 오드랜드 패이로드 (2026-09-07)&quot;">​</a></h2><p>오드랜드 에셋은 생성 경로가 아닙니다. 소유자 자작 프로젝트의 그래픽·SFX·VFX는 <strong>기증 경로</strong>로 들어옵니다. 2026-09-07 소유자가 오드랜드의 모든 그래픽 에셋을 이 프로젝트에서 자유롭게 쓰도록 선언했고, 같은 날 전량 반입을 지시했습니다(<a href="https://github.com/islee23520/seoul-kenshi/blob/main/Intent.md" target="_blank" rel="noreferrer">Intent</a> 결정 4). 실시간 진형·카드 전투는 미리 렌더된 다이아몬드 아이소 타일을 요구하지 않으므로 오드랜드의 3D FBX·재질·애니메이션을 고정 카메라 아래에 그대로 놓고 씁니다.</p><ul><li><strong>위치</strong>: <code>Game/Assets/Quarantine/Oddland/</code> — <code>/Quarantine/</code> 경로 표시 때문에 런타임 프로비넌스 감사가 이 트리를 항상 격리 등급으로 분류합니다. 슬롯 승격 없이는 재생 가능한 씨에서 도달할 수 없습니다. 원본의 <code>Resources</code> 폴더는 <code>Res</code>로 이름을 바꿔 빌드에 자동 포함되지 않게 합니다.</li><li><strong>범위</strong>: 3D 모델·재질·애니메이션·PSD/PNG 텍스처·아이콘·아틀라스·폰트·SFX(wav/ogg/mp3)·VFX 프리팽·셸이더·후처리 프로필·Spine 스켈레톤 데이터와 spine-unity 런타임. 싼, UI 화면 프리팽, 게임 로직 스크립트, 메타데이터, 서드파티 도구는 가져오지 않습니다.</li><li><strong>재현</strong>: <code>node tools/art/import-oddland-donor.mjs</code>가 외부 볼륨의 오드랜드 체크아웃에서 결정론적으로 복사하고 <code>docs/assets/bom/donor/oddland-donor-import.json</code>과 SHA-256 목록을 씁니다. <code>--verify</code>가 페이로드를 목록과 대조합니다 — 에디터가 임포트 때 다시 직렬화하는 YAML(.meta·.mat 등)은 업그레이드로 보고만 하고, FBX·PNG·PSD·WAV 같은 바이너리 원본의 불일치만 실패로 판정합니다. 페이로드(약 1.6GB)는 LFS 할당량을 넘어 git에 넣지 않고 매니페스트만 추적합니다.</li><li><strong>권리</strong>: BOM <code>rights_status: allowed</code>, 근거는 2026-09-07 소유자 선언과 기증자 커밋 해시입니다. spine-unity 런타임은 Esoteric Software 런타임 라이선스를 따르며 소유자의 Spine 에디터 라이선스가 전제입니다 — 이것은 그래픽 에셋 권리가 아니라 도구 라이선스입니다.</li><li><strong>승격</strong>: 기증 페이로드에서 런타임 슬롯으로 올리는 것은 여전히 아래 「에셋마다 남기는 기록」의 BOM·<code>look.owner_verdict: accepted</code>·소스 바인딩 영수증을 거칩니다. 기증은 승격이 아닙니다.</li><li><strong>카탈로그</strong>: <code>docs/assets/bom/donor/oddland-asset-catalog.json</code>·<code>.md</code>가 비-.meta 7,712개 전량을 kind·family·처분으로 분류한다(미분류 0). <code>node tools/art/catalog-oddland-donor.mjs</code>로 재생성, <code>--check</code>로 멱등 검증, <code>--summary</code>로 요약. 분류는 사용 준비도 판정이 아니며 승격은 아래 승격 절차를 그대로 따른다.</li></ul><h2 id="ui-아트-임포트와-합성" tabindex="-1">UI 아트 임포트와 합성 <a class="header-anchor" href="#ui-아트-임포트와-합성" aria-label="Permalink to &quot;UI 아트 임포트와 합성&quot;">​</a></h2><p>UI 아트는 원본 바이트를 <code>Texture2D.LoadImage</code>로 우회하지 않고 <code>AssetDatabase</code>가 가져온 텍스처를 씁니다. 임포터의 <code>maxTextureSize</code>를 포함한 설정을 존중하며, 그 한도가 실제로 적용됐는지를 검증합니다.</p><p>합성은 source-over입니다. 알파 식은 <code>outA = srcA + dstA * (1 - srcA)</code>이며, 색은 premultiplied 알파로 섞습니다. <code>SetPixels</code>로 목적지를 통째로 덮어쓰지 않습니다. 완전 투명 소스가 목적지에 구멍을 뚫으면 계약 위반입니다.</p><h2 id="에셋마다-남기는-기록" tabindex="-1">에셋마다 남기는 기록 <a class="header-anchor" href="#에셋마다-남기는-기록" aria-label="Permalink to &quot;에셋마다 남기는 기록&quot;">​</a></h2><p>출시 후보 에셋마다 입력 자료의 권리와 해시, 작업 순서, 시드, 모델과 노드 버전, 원본 출력, Blender 수정, Unity 설정과 사람의 승인 기록을 남깁니다. 필수 필드는 <code>tools/art/asset-manifest.schema.json</code>이고 <code>validate-manifest</code>가 검사합니다. 그래프 컴파일 결과와 분기 검사 코드도 함께 남깁니다. <code>blocked</code> 또는 <code>unresolved</code> 값이 하나라도 있으면 프로젝트 에셋으로 받아들이지 않습니다.</p><p>생성 전에 에셋마다 <code>look</code>을 적습니다. <code>palette</code>(색 값), <code>materials</code>(거칠기·금속·마감), <code>references</code>(근거 문서나 사진 경로)가 비어 있으면 검수·승격을 진행하지 않습니다. 프롬프트만으로 재질을 대신하지 않습니다. 소유자 판정은 <code>look.owner_verdict</code>의 <code>pending</code> · <code>accepted</code> · <code>rejected</code>입니다.</p>`,38)])])}const k=o(s,[["render",c]]);export{m as __pageData,k as default};
